  ('kurinye-krylya-v-medovo-chesnochnoy-glazuri', 'main', false, null, 70, 430, 4, 'medium',
   '{"ru":"Куриные крылья в медово-чесночной глазури","en":"Honey-garlic glazed chicken wings"}'::jsonb,
   '{"ru":"Липкая блестящая глазурь, обожжённая жаром духовки, с кунжутом и лимоном. Мёд добавляется в конце, чтобы не сгорел.","en":"A sticky, glossy glaze caramelised by oven heat, finished with sesame and lemon. The honey goes on late so it never burns."}'::jsonb,
   '{"ru":["Куриные крылья — 900 г","Мёд — 2 ст. л.","Соевый соус — 45 мл","Чеснок — 3 зубчика","Паприка — 1 ч. л.","Растительное масло — 25 мл","Лимон — 1/2 шт","Кунжут — 1 ч. л.","Петрушка — 10 г","Соль, перец — по вкусу"],"en":["Chicken wings — 900 g","Honey — 2 tbsp","Soy sauce — 45 ml","Garlic — 3 cloves","Paprika — 1 tsp","Vegetable oil — 25 ml","Lemon — 1/2","Sesame — 1 tsp","Parsley — 10 g","Salt, pepper — to taste"]}'::jsonb,
   '{"ru":["Разделите крылья на части и хорошо обсушите кожу — так корочка будет лучше.","Смешайте маринад из мёда, соевого соуса, чеснока, паприки и масла.","Обмажьте крылья и оставьте на 20 минут.","Разложите на противень и запекайте при 200 °C 25 минут.","Смажьте оставшейся глазурью и допеките 5 минут; посыпьте кунжутом и петрушкой, сбрызните лимоном."],"en":["Joint the wings and pat the skin very dry for a better crust.","Mix a marinade of honey, soy sauce, garlic, paprika and oil.","Coat the wings and rest for 20 minutes.","Spread on a tray and bake at 200 °C for 25 minutes.","Brush with the remaining glaze and bake 5 minutes more; scatter sesame and parsley, squeeze over lemon."]}'::jsonb,
   '{"ru":["закуски к пиву","курица","запечённое"],"en":["beer snacks","chicken","baked"]}'::jsonb)
