  ('rzhanye-grenki-s-chesnokom-i-syrnym-dipom', 'snack', false, null, 30, 250, 6, 'easy',
   '{"ru":"Ржаные гренки с чесноком и сырным дипом","en":"Rye garlic croutons with cheese dip"}'::jsonb,
   '{"ru":"Ароматные ржаные брусочки, запечённые до хруста в чесночном масле, и тёплый сырный соус на сливках. Классика к пиву без фритюра.","en":"Fragrant rye batons baked crisp in garlic butter, with a warm cream-and-cheese dip. A beer classic without the deep fryer."}'::jsonb,
   '{"ru":["Ржаной хлеб — 350 г","Чеснок — 3 зубчика","Растительное масло — 35 мл","Твёрдый сыр — 120 г","Сливки 20% — 140 мл","Петрушка — 10 г","Паприка — 1/2 ч. л.","Соль, перец — по вкусу"],"en":["Rye bread — 350 g","Garlic — 3 cloves","Vegetable oil — 35 ml","Hard cheese — 120 g","Cream 20% — 140 ml","Parsley — 10 g","Paprika — 1/2 tsp","Salt, pepper — to taste"]}'::jsonb,
   '{"ru":["Нарежьте хлеб одинаковыми брусочками.","Смешайте масло с тёртым чесноком, паприкой и солью и смажьте брусочки.","Запекайте при 180 °C 12–15 минут до хруста.","Прогрейте сливки на слабом огне, всыпьте тёртый сыр и растопите до гладкости, не доводя до кипения.","Подавайте гренки сразу с тёплым сырным дипом."],"en":["Cut the bread into even batons.","Mix oil with grated garlic, paprika and salt and brush the batons.","Bake at 180 °C for 12–15 minutes until crisp.","Warm the cream over low heat, add grated cheese and melt smooth without boiling.","Serve the croutons right away with the warm cheese dip."]}'::jsonb,
   '{"ru":["закуски к пиву","гренки","запечённое"],"en":["beer snacks","croutons","baked"]}'::jsonb)
